def lps(s: str) -> int:
    def longest_palindromic_subsequence(s):
        n = len(s)
        # Create a 2D array to store the results of subproblems
        dp = [[0] * n for _ in range(n)]

        # Strings of length 1 are palindrome of length 1
        for i in range(n):
            dp[i][i] = 1

        # Build the table. Note that the lower diagonal values of table are 
        # useless and not filled in the process. l is the length of substring
        for l in range(2, n + 1):
            for i in range(n - l + 1):
                j = i + l - 1
                if s[i] == s[j] and l == 2:
                    dp[i][j] = 2
                elif s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

        return dp[0][n - 1]

    # Convert the input string to upper case to ignore case sensitivity
    s = s.upper()
    return longest_palindromic_subsequence(s.replace(" ", ""))
